import { test, expect } from "vitest";
import { detectChallenge } from "./challenge.ts";
test("development-active-challenge", () => {
  expect(detectChallenge("<html><body><main><h1>Verify you are human</h1><form action=\"/challenge\"><input name=\"captcha-response\"><button>Verify</button></form></main></body></html>")).toBe(true);
});
test("development-listings", () => {
  expect(detectChallenge("<html><body><main><article data-listing-id=\"101\">Apartment</article><article data-listing-id=\"102\">Studio</article></main></body></html>")).toBe(false);
});
test("holdout-copy", () => {
  expect(detectChallenge("<html><body><article><h1>Captcha research office for sale</h1><p>Verify you are human is printed on the poster.</p></article></body></html>")).toBe(false);
});
test("holdout-hidden-widget", () => {
  expect(detectChallenge("<html><body><article data-listing-id=\"103\">Apartment</article><div hidden><form action=\"/challenge\"><input name=\"captcha-response\"><button>Verify</button></form></div></body></html>")).toBe(false);
});
test("holdout-ordinary-widget", () => {
  expect(detectChallenge("<html><body><article data-listing-id=\"104\">Apartment</article><form action=\"/contact\"><input name=\"captcha-response\"><button>Send enquiry</button></form></body></html>")).toBe(false);
});
test("holdout-challenge", () => {
  expect(detectChallenge("<html><body><main><h1>Security check</h1><p>Please complete the challenge to continue</p><form action=\"/challenge\"><input name=\"captcha-response\"><button>Continue</button></form></main></body></html>")).toBe(true);
});
test("holdout-script-only", () => {
  expect(detectChallenge("<html><body><article data-listing-id=\"105\">Apartment</article><script>const example=\"Verify you are human\";</script></body></html>")).toBe(false);
});
test("holdout-ordinary-form", () => {
  expect(detectChallenge("<html><body><form action=\"/search\"><input name=\"query\"><button>Search</button></form><p>Property search</p></body></html>")).toBe(false);
});
